import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { setUnit, topic, deck, sl, plot, table, flow, build, chapterTests } from '../../cbse-12-mathematics-ch01/src/lib.mjs';
import { r, fr, sum, prod, P, cond, dice2, cards, coins, draws, bag, tree, venn, partition } from './prob.mjs';

setUnit('cbse-12-mathematics-ch13');
await import('./questions.mjs');
const DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const must = (cond0, msg) => { if (!cond0) throw new Error(`self-check failed: ${msg}`); };
const f = (s) => `\\frac{${s.split('/')[0]}}{${s.split('/')[1]}}`;

// ---------------------------------------------------------------- worked examples, recomputed
// Deck 1
const we1 = cond(dice2, (w) => w[0] + w[1] >= 10, (w) => w[0] === 6 || w[1] === 6);
must(we1.eq(fr(5, 11)) && dice2.filter((w) => w[0] === 6 || w[1] === 6).length === 11, 'WE1 5/11 of 11');
const jai = { n: 80, c: 50, fb: 35, both: 20 };
must(fr(jai.both, jai.c).eq(fr(2, 5)) && fr(jai.both, jai.fb).eq(fr(4, 7)) && jai.n - (jai.c + jai.fb - jai.both) === 15, 'WE2');
const bulbs = bag({ F: 3, G: 7 });
const bsp = draws(bulbs, 2);
must(P(bsp, (w) => w[0] === 'F' && w[1] === 'F').eq(fr(1, 15)) && P(bsp, (w) => w[0] !== w[1]).eq(fr(7, 15)), 'WE3');
must(P(draws(bag({ R: 4, G: 3, Y: 2 }), 3), (w) => w.join('') === 'RGY').eq(fr(1, 21)), 'WE4');
const srv = prod(fr(0.9), fr(0.95), fr(0.98));
must(srv.eq(fr(0.8379)) && srv.comp().eq(fr(0.1621)), 'WE5');
must(P(cards, (c) => c.rank === 13 && c.suit === 'H').eq(P(cards, (c) => c.rank === 13).mul(P(cards, (c) => c.suit === 'H'))), 'king/heart independent');
must(cond(coins(2), (w) => w[1] === 'H', (w) => w[0] === 'H').eq(fr(1, 2)), 'coin tree');
// Deck 2
const b1 = prod(fr(1, 2), fr(5, 8)), b2 = prod(fr(1, 2), fr(2, 8));
must(b1.add(b2).eq(fr(7, 16)) && b1.div(b1.add(b2)).eq(fr(5, 7)), 'D2 WE1/WE3');
const route = sum(prod(fr(1, 2), fr(1, 10)), prod(fr(1, 3), fr(1, 5)), prod(fr(1, 6), fr(1, 4)));
must(route.eq(fr(19, 120)), 'D2 WE2');
must(fr(45, 45 + 95).eq(fr(9, 28)) && Math.round(0.05 * 1000 * 0.9) === 45 && Math.round(0.95 * 1000 * 0.1) === 95, 'D2 WE4');
const shifts = [prod(fr(0.4), fr(0.02)), prod(fr(0.35), fr(0.03)), prod(fr(0.25), fr(0.04))];
const pC = sum(...shifts);
must(pC.eq(fr(0.0285)) && shifts.map((x) => x.div(pC).toString()).join() === '16/57,7/19,20/57', 'D2 WE5');
const post = (p) => (0.9 * p) / (0.8 * p + 0.1);
must(Math.abs(post(0.1) - 0.5) < 1e-12 && Math.abs(post(0.5) - 0.9) < 1e-12, 'posterior curve');

// ---------------------------------------------------------------- visuals
const vennAB = venn({ alt: 'Venn diagram: a rectangle for the sample space S containing two overlapping circles A and B. The overlap is the event A and B both happening.', caption: r`Given $B$, only the circle $B$ matters; the favourable part is the overlap $A \cap B$.` });
const diceGrid = table(['', '$1$', '$2$', '$3$', '$4$', '$5$', '$6$'], [1, 2, 3, 4, 5, 6].map((a) => [`$${a}$`, ...[1, 2, 3, 4, 5, 6].map((b) => `$${a + b}$`)]), 'Six by six table of the sums of two dice: rows for the first die from 1 to 6, columns for the second die from 1 to 6, each cell the sum, from 2 in the top left to 12 in the bottom right.', 'The $36$ equally likely outcomes of two dice, shown by their sums.');
const shrink = table(['Question', 'Sample space', 'Favourable', 'Probability'], [['$P(4)$ on a die', r`$\{1, 2, 3, 4, 5, 6\}$`, r`$\{4\}$`, r`$\dfrac{1}{6}$`], ['$P(4 \\mid \\text{even})$', r`$\{2, 4, 6\}$`, r`$\{4\}$`, r`$\dfrac{1}{3}$`]], 'Table comparing two questions about one die. Without information the sample space has six outcomes and the chance of a four is one sixth. Told the number is even, the sample space shrinks to 2, 4, 6 and the chance of a four becomes one third.', 'New information shrinks the sample space.');
must(cond([[1], [2], [3], [4], [5], [6]], (w) => w[0] === 4, (w) => w[0] % 2 === 0).eq(fr(1, 3)), 'shrink table');
const we1Table = table(['Outcomes with at least one six', 'Sum $\\ge 10$?'], [['$(6, 1), (6, 2), (6, 3)$', 'no'], ['$(1, 6), (2, 6), (3, 6)$', 'no'], ['$(6, 4), (4, 6)$', 'yes'], ['$(6, 5), (5, 6)$', 'yes'], ['$(6, 6)$', 'yes']], 'Table of the eleven outcomes with at least one six, grouped: six outcomes with sum less than 10 and five outcomes, (6,4), (4,6), (6,5), (5,6), (6,6), with sum at least 10.', '$5$ favourable out of $11$: $P = \\dfrac{5}{11}$.');
const propTable = table(['Property', 'Statement'], [['Whole space', r`$P(S \mid F) = P(F \mid F) = 1$`], ['Union', r`$P(A \cup B \mid F) = P(A \mid F) + P(B \mid F) - P(A \cap B \mid F)$`], ['Complement', r`$P(A' \mid F) = 1 - P(A \mid F)$`], ['Range', r`$0 \le P(A \mid F) \le 1$`]], 'Table of properties of conditional probability: the whole sample space given F has probability 1; the union rule holds given F; the complement rule holds given F; every conditional probability lies between 0 and 1.', 'Conditional probability behaves like ordinary probability on the new sample space $F$.');
const jaiTable = table(['', 'Football', 'No football', 'Total'], [['Cricket', '$20$', '$30$', '$50$'], ['No cricket', '$15$', '$15$', '$30$'], ['Total', '$35$', '$45$', '$80$']], 'Two-way table of 80 Jaipur students: 20 like both cricket and football, 30 cricket only, 15 football only, 15 neither; totals 50 cricket, 35 football.', 'Divide by the row total for "given cricket", by the column total for "given football".');
must(20 + 30 === jai.c && 20 + 15 === jai.fb && 20 + 30 + 15 + 15 === jai.n, 'jaipur table');
const twoWay = table(['', r`$P(\text{football} \mid \text{cricket})$`, r`$P(\text{cricket} \mid \text{football})$`], [['Calculation', r`$\dfrac{20}{50}$`, r`$\dfrac{20}{35}$`], ['Value', r`$\dfrac{2}{5}$`, r`$\dfrac{4}{7}$`]], 'Table: the probability of football given cricket is 20 over 50, two fifths; the probability of cricket given football is 20 over 35, four sevenths. Same numerator, different denominators.', r`$P(A \mid B)$ and $P(B \mid A)$ share the numerator but not the denominator.`);
const coinTree = tree({ root: 'Toss', first: [['$H$', '$\\frac{1}{2}$'], ['$T$', '$\\frac{1}{2}$']], second: [[['$HH$', '$\\frac{1}{2}$'], ['$HT$', '$\\frac{1}{2}$']], [['$TH$', '$\\frac{1}{2}$'], ['$TT$', '$\\frac{1}{2}$']]], alt: 'Tree diagram for two coin tosses: the first toss branches to head and tail, each with probability one half; each of these branches again to head and tail with probability one half, giving four end points HH, HT, TH, TT.', caption: 'Multiply along a path: each of the four outcomes has probability $\\frac{1}{4}$.' });
const bulbTree = tree({ root: 'Box', first: [['Fused', `$${f('3/10')}$`], ['Good', `$${f('7/10')}$`]], second: [[['Fused', `$${f('2/9')}$`], ['Good', `$${f('7/9')}$`]], [['Fused', `$${f('3/9')}$`], ['Good', `$${f('6/9')}$`]]], alt: 'Tree diagram for taking two bulbs from a box of 10 with 3 fused. First bulb fused with probability 3 over 10, good with 7 over 10. After a fused bulb, the second is fused with probability 2 over 9 and good with 7 over 9; after a good bulb, fused with 3 over 9 and good with 6 over 9.', caption: 'Second-stage branches are conditional probabilities: they change with the first draw.' });
must(fr(3, 10).mul(fr(2, 9)).eq(fr(1, 15)) && fr(3, 10).mul(fr(7, 9)).add(fr(7, 10).mul(fr(3, 9))).eq(fr(7, 15)), 'bulb tree');
const bagTree3 = flow('LR', [['a', 'Red first: $\\dfrac{4}{9}$'], ['b', 'Green second: $\\dfrac{3}{8}$'], ['c', 'Yellow third: $\\dfrac{2}{7}$'], ['d', 'Product: $\\dfrac{1}{21}$']], [['a', 'b', 'then'], ['b', 'c', 'then'], ['c', 'd', 'multiply']], 'Chain of three draws without replacement: red first with probability 4 over 9, then green with 3 over 8, then yellow with 2 over 7; the product is 1 over 21.', 'Each factor is conditional on the draws before it.');
must(prod(fr(4, 9), fr(3, 8), fr(2, 7)).eq(fr(1, 21)), 'chain');
const multTable = table(['Number of events', 'Multiplication rule'], [['Two', r`$P(E \cap F) = P(E)\,P(F \mid E)$`], ['Three', r`$P(E \cap F \cap G) = P(E)\,P(F \mid E)\,P(G \mid E \cap F)$`]], 'Table of the multiplication rule: for two events, probability of E and F equals probability of E times probability of F given E; for three events a third factor, probability of G given E and F, is added.', 'Multiply along the order in which things happen.');
const kingHeart = table(['Event', 'Count', 'Probability'], [['King ($K$)', '$4$', r`$\dfrac{1}{13}$`], ['Heart ($H$)', '$13$', r`$\dfrac{1}{4}$`], ['King of hearts ($K \\cap H$)', '$1$', r`$\dfrac{1}{52}$`]], 'Table for one card from a pack of 52: a king has probability 1 over 13, a heart 1 over 4, the king of hearts 1 over 52, which equals the product of the first two.', r`$\dfrac{1}{13} \times \dfrac{1}{4} = \dfrac{1}{52}$: $K$ and $H$ are independent.`);
const exclVsIndep = table(['', 'Mutually exclusive', 'Independent'], [['Meaning', 'cannot happen together', 'one does not change the chance of the other'], ['Test', r`$P(A \cap B) = 0$`, r`$P(A \cap B) = P(A)\,P(B)$`], ['Venn picture', 'circles do not overlap', 'overlap has the "right" size'], ['Both at once?', 'only if $P(A) = 0$ or $P(B) = 0$', '']], 'Comparison table of mutually exclusive and independent events: meaning, the test, what the Venn picture looks like, and the fact that with non-zero probabilities the two cannot both hold.', 'Two different ideas: do not mix them up.');
const serverFlow = flow('LR', [['a', 'All three work: $0.9 \\times 0.95 \\times 0.98 = 0.8379$'], ['b', 'At least one fails: $1 - 0.8379 = 0.1621$']], [['a', 'b', 'complement']], 'Flow: the probability that all three servers work is 0.9 times 0.95 times 0.98, which is 0.8379; the probability that at least one fails is 1 minus that, 0.1621.', '"At least one" is easiest through the complement "none".');
const summary1 = table(['Idea', 'Formula'], [['Conditional probability', r`$P(E \mid F) = \dfrac{P(E \cap F)}{P(F)}$`], ['Complement', r`$P(E' \mid F) = 1 - P(E \mid F)$`], ['Multiplication rule', r`$P(E \cap F) = P(E)\,P(F \mid E)$`], ['Independence', r`$P(E \cap F) = P(E)\,P(F)$`], ['At least one (independent)', r`$1 - P(E')\,P(F')$`]], 'Summary table of part one: conditional probability formula, complement rule, multiplication rule, the independence test and the at-least-one rule using complements.', 'Part 1 on one card.');
// deck 2 visuals
const part3 = partition({ labels: ['$E_1$', '$E_2$', '$E_3$'], alt: 'A rectangle for the sample space split into three vertical strips E1, E2 and E3 that do not overlap and fill the rectangle. A circle for the event A crosses all three strips.', caption: r`$A$ is cut into $A \cap E_1$, $A \cap E_2$, $A \cap E_3$: add their probabilities.` });
const bagTree = tree({ root: 'Coin', first: [['Bag I', `$${f('1/2')}$`], ['Bag II', `$${f('1/2')}$`]], second: [[['White', `$${f('5/8')}$`], ['Black', `$${f('3/8')}$`]], [['White', `$${f('2/8')}$`], ['Black', `$${f('6/8')}$`]]], alt: 'Tree diagram: a coin chooses bag one or bag two, each with probability one half. From bag one, white with probability 5 over 8 and black 3 over 8. From bag two, white 2 over 8 and black 6 over 8.', caption: r`$P(W) = \frac{1}{2} \cdot \frac{5}{8} + \frac{1}{2} \cdot \frac{2}{8} = \frac{7}{16}$.` });
const routeTable = table(['Route', 'P(route)', 'P(delay | route)', 'Product'], [['Ring road', r`$\dfrac{1}{2}$`, r`$\dfrac{1}{10}$`, r`$\dfrac{1}{20}$`], ['City centre', r`$\dfrac{1}{3}$`, r`$\dfrac{1}{5}$`, r`$\dfrac{1}{15}$`], ['Old town', r`$\dfrac{1}{6}$`, r`$\dfrac{1}{4}$`, r`$\dfrac{1}{24}$`], ['Total', '$1$', '', r`$\dfrac{19}{120}$`]], 'Table for a Chennai courier with three routes: ring road probability one half and delay one tenth, product one twentieth; city centre one third and one fifth, product one fifteenth; old town one sixth and one quarter, product one twenty-fourth. The products add to 19 over 120.', 'Total probability: add the products over the partition.');
must(fr(1, 20).add(fr(1, 15)).add(fr(1, 24)).eq(fr(19, 120)), 'route table');
const bayesFlow = flow('TB', [['a', 'Name the partition $E_1, \\ldots, E_n$ (the possible causes)'], ['b', 'Write priors $P(E_i)$ and likelihoods $P(A \\mid E_i)$'], ['c', 'Multiply: $P(E_i)\\,P(A \\mid E_i)$ for each $i$'], ['d', 'Add the products: $P(A)$'], ['e', 'Divide: $P(E_i \\mid A) = \\dfrac{P(E_i)\\,P(A \\mid E_i)}{P(A)}$'], ['f', 'Check: posteriors add to $1$']], [['a', 'b'], ['b', 'c'], ['c', 'd'], ['d', 'e'], ['e', 'f']], 'Bayes recipe as a flow: name the partition, write priors and likelihoods, multiply for each cause, add the products to get the probability of A, divide each product by that total, and check that the answers add to 1.', 'Bayes in five steps.');
const bayesTreeAns = tree({ root: 'Coin', first: [['Bag I', `$${f('1/2')}$`], ['Bag II', `$${f('1/2')}$`]], second: [[['White: $\\frac{5}{16}$', `$${f('5/8')}$`]], [['White: $\\frac{2}{16}$', `$${f('2/8')}$`]]], alt: 'Tree with only the white branches kept: bag one then white has path probability 5 over 16; bag two then white has path probability 2 over 16.', caption: r`$P(\text{Bag I} \mid W) = \dfrac{5/16}{5/16 + 2/16} = \dfrac{5}{7}$.` });
const screenTable = table(['Per 1000 people', 'Positive', 'Negative', 'Total'], [['Deficient', '$45$', '$5$', '$50$'], ['Not deficient', '$95$', '$855$', '$950$'], ['Total', '$140$', '$860$', '$1000$']], 'Natural-frequency table for 1000 people at a screening camp: 50 deficient, of whom 45 test positive and 5 negative; 950 not deficient, of whom 95 test positive and 855 negative; 140 positives in all.', r`Of $140$ positives, only $45$ are deficient: $\dfrac{45}{140} = \dfrac{9}{28}$.`);
must(45 + 5 === 50 && 95 + 855 === 950 && 45 + 95 === 140, 'screen table');
const priorPlot = plot({ x: [0, 1], y: [0, 1], xl: 'prior P(E)', yl: 'posterior P(E | +)', fns: [{ expr: '0.9*x/(0.8*x+0.1)', label: 'posterior' }, { expr: 'x', label: 'no change' }], pts: [[0.1, 0.5, '(0.1, 0.5)'], [0.5, 0.9, '(0.5, 0.9)']] }, 'Graph of the posterior probability after a positive test against the prior, for a test that is positive 90 percent of the time when the condition is present and 10 percent when absent. The curve rises steeply from 0, passes (0.1, 0.5) and (0.5, 0.9), and lies above the diagonal line of no change.', 'A positive result always raises the probability, but a small prior still gives a modest posterior.');
const shiftTable = table(['Shift', 'Share of calls', 'Complaint rate', 'Product', 'Posterior'], [['Morning', '$0.40$', '$0.02$', '$0.008$', r`$\dfrac{16}{57}$`], ['Evening', '$0.35$', '$0.03$', '$0.0105$', r`$\dfrac{7}{19}$`], ['Night', '$0.25$', '$0.04$', '$0.01$', r`$\dfrac{20}{57}$`], ['Total', '$1$', '', '$0.0285$', '$1$']], 'Table for a Hyderabad call centre: morning shift 40 percent of calls with complaint rate 2 percent, product 0.008, posterior 16 over 57; evening 35 percent and 3 percent, product 0.0105, posterior 7 over 19; night 25 percent and 4 percent, product 0.01, posterior 20 over 57. Total 0.0285.', 'The evening shift is the most likely source of a complaint.');
const trapTable = table(['Question asks for', 'Tool'], [[r`$P(A)$ when $A$ can happen through several causes`, 'Total probability (add products)'], [r`$P(\text{cause} \mid A)$ after seeing $A$`, "Bayes' theorem (one product over the sum)"], [r`$P(A \mid \text{cause})$`, 'Read it from the question: a likelihood'], ['A final check', 'Posteriors over a partition add to $1$']], 'Table of common traps: the probability of an outcome through several causes needs total probability; the probability of a cause after seeing the outcome needs Bayes; the probability of the outcome given a cause is simply read from the question; posteriors must add to one.', 'Decide the direction of the question before calculating.');
const toolFlow = flow('TB', [['q', 'What does the question give and ask?'], ['c', '"Given that" one event: **conditional probability**'], ['m', 'Events in sequence: **multiplication rule**'], ['i', 'Unrelated trials: **independence**, multiply'], ['t', 'Outcome through several causes: **total probability**'], ['b', 'Cause, given the outcome: **Bayes**']], [['q', 'c'], ['q', 'm'], ['q', 'i'], ['q', 't'], ['q', 'b']], 'Decision chart for the chapter: from what the question gives and asks, choose conditional probability, the multiplication rule, independence, total probability or Bayes theorem.', 'One question, five possible tools.');
const summary2 = table(['Result', 'Formula'], [['Partition', r`$E_i \cap E_j = \varnothing$, $\bigcup E_i = S$, $P(E_i) > 0$`], ['Total probability', r`$P(A) = \sum P(E_i)\,P(A \mid E_i)$`], ["Bayes' theorem", r`$P(E_i \mid A) = \dfrac{P(E_i)\,P(A \mid E_i)}{\sum_j P(E_j)\,P(A \mid E_j)}$`], ['Check', r`$\sum_i P(E_i \mid A) = 1$`]], "Summary table of part two: definition of a partition, the theorem of total probability, Bayes' theorem and the check that posteriors add to one.", 'Part 2 on one card.');

// ---------------------------------------------------------------- deck 1
const d1 = deck({
  part: 1,
  title: 'Probability — Part 1: Conditional probability and independence',
  goals: ['Find conditional probabilities from sample spaces, tables and formulas', 'Use the properties of conditional probability', 'Apply the multiplication rule to events in sequence', 'Test events for independence and tell independence apart from mutual exclusion'],
  slides: [
    sl('title', 'Probability, Part 1: When you already know something', { b: 'Probability changes when information arrives.', v: vennAB, n: 'Welcome to probability in class twelve. In class ten you found chances by counting equally likely outcomes. Now we ask a sharper question: how should a probability change when we learn that something has already happened? The picture shows two events inside a sample space. Once we know that B has happened, only the circle B matters. That simple idea drives this whole chapter.' }),
    sl('concept', 'What you will be able to do', { ul: ['Find **conditional probability** $P(E \\mid F)$', 'Use its **properties**, including the complement rule', 'Apply the **multiplication rule** for two or three events', 'Test whether events are **independent**', 'Tell **independent** from **mutually exclusive**'], n: 'Here are the goals for part one. You will compute conditional probabilities in three ways: by listing outcomes, from a table, and with a formula. Then you will use the multiplication rule for events that happen one after another, and finally you will learn what it means for two events to be independent, and why that is very different from being mutually exclusive.' }),
    sl('concept', 'Recap: equally likely outcomes', { b: 'For equally likely outcomes, $P(E) = \\dfrac{\\text{number of outcomes in } E}{\\text{number of outcomes in } S}$.', v: diceGrid, n: 'A quick recap. When two dice are thrown there are thirty six equally likely outcomes, shown here by their sums. The probability of an event is the number of favourable outcomes divided by thirty six. For example, a sum of seven appears six times, so its probability is one sixth. Keep this grid in mind; we will reuse it many times.' }),
    sl('diagram', 'Information shrinks the sample space', { b: 'If we know $F$ has happened, the outcomes outside $F$ are ruled out; those inside $F$ stay equally likely.', v: shrink, n: 'A die is thrown. The chance of a four is one sixth. Now suppose a friend peeks and says the number is even. Only two, four and six remain possible, and they are still equally likely. So the chance of a four becomes one third. The information did not change the die; it changed what we know, and so it changed the sample space we count in.' }),
    sl('concept', 'Conditional probability', { b: 'For events $E$, $F$ with $P(F) \\ne 0$, the **probability of $E$ given $F$** is', m: ['P(E \\mid F) = \\dfrac{P(E \\cap F)}{P(F)}'], ul: ['Only the part of $E$ inside $F$ counts', 'Dividing by $P(F)$ rescales $F$ to total probability $1$', 'For equally likely outcomes: $P(E \\mid F) = \\dfrac{n(E \\cap F)}{n(F)}$'], v: vennAB, n: 'Here is the definition. The probability of E given F is the probability of E and F together, divided by the probability of F. In the picture, F becomes the whole world, and only the overlap with E is favourable. Dividing by the probability of F rescales F so that it has total probability one. With equally likely outcomes, simply count the overlap and divide by the count of F.' }),
    sl('example', 'Worked example 1: two dice', { b: 'Two dice are thrown. Given that at least one shows $6$, find the probability that the sum is at least $10$.', ul: ['**Step 1 —** $F$: at least one six. List: $11$ outcomes.', '**Step 2 —** Inside $F$, sum $\\ge 10$: $(6, 4), (4, 6), (6, 5), (5, 6), (6, 6)$, five outcomes.', '**Step 3 —** $P(E \\mid F) = \\dfrac{5}{11}$.', '**Check —** Formula: $\\dfrac{5/36}{11/36} = \\dfrac{5}{11}$ ✓'], v: we1Table, n: 'First list the given event: at least one six. There are eleven such outcomes, not twelve, because double six must be counted once. Inside these eleven, look for a sum of at least ten. There are five. So the answer is five out of eleven. The formula gives the same thing: five over thirty six divided by eleven over thirty six.' }),
    sl('check', 'Quick check: given the event itself', { b: 'What is $P(A \\mid A)$ for an event with $P(A) > 0$?', chk: 'm03', n: 'Think about what the given information tells you. If you already know that A has happened, how likely is A? Use the formula if you want to be sure.' }),
    sl('concept', 'Properties of conditional probability', { b: 'Given $F$, probability works exactly as usual on the new sample space $F$.', v: propTable, n: 'Conditional probability obeys all the familiar rules. Given F, the whole sample space has probability one. The addition rule for a union still holds. And the complement rule holds: the probability of not E given F is one minus the probability of E given F. These properties save time, because you can switch to the complement whenever it is easier to count.' }),
    sl('example', 'Worked example 2: a two-way table', { b: 'A Jaipur school surveyed $80$ students: $50$ like cricket, $35$ like football and $20$ like both. A student is chosen at random.', ul: ['$P(\\text{football} \\mid \\text{cricket}) = \\dfrac{20}{50} = \\dfrac{2}{5}$', '$P(\\text{cricket} \\mid \\text{football}) = \\dfrac{20}{35} = \\dfrac{4}{7}$', 'Neither: $80 - (50 + 35 - 20) = 15$ students'], v: jaiTable, n: 'Put the survey into a two-way table first. Twenty like both games, thirty like cricket only, fifteen football only and fifteen neither. For the probability of football given cricket, look only at the cricket row: twenty out of fifty, which is two fifths. For cricket given football, look only at the football column: twenty out of thirty five, which is four sevenths.' }),
    sl('check', 'Quick check: face cards', { b: 'Given that a card drawn from a pack is a face card, how likely is it to be a king?', chk: 'm06', n: 'First decide how many face cards there are in a pack. Then count how many of those are kings. The given information is your new sample space.' }),
    sl('diagram', 'The order matters: P(A | B) versus P(B | A)', { b: 'Same overlap on top, different event at the bottom.', v: twoWay, n: 'A common mistake is to treat the probability of A given B as the same as B given A. Both have the same numerator, the overlap. But one divides by the size of B and the other by the size of A. In our survey, football given cricket is two fifths, while cricket given football is four sevenths. Always ask: which event is known?' }),
    sl('concept', 'The multiplication rule', { b: 'Rearranging the definition gives the probability that two events both happen.', m: ['P(E \\cap F) = P(E)\\,P(F \\mid E) = P(F)\\,P(E \\mid F)'], v: multTable, n: 'Multiply both sides of the definition by the probability of the given event, and you get the multiplication rule. The probability that E and F both happen is the probability of E times the probability of F given E. For three events, keep going: multiply by the probability of the third event given the first two. This is ideal for events that happen in order, such as successive draws.' }),
    sl('example', 'Worked example 3: drawing without replacement', { b: 'A box at a Ludhiana shop has $10$ bulbs, $3$ of them fused. Two bulbs are taken one after the other without replacement.', ul: ['Both fused: $\\dfrac{3}{10} \\times \\dfrac{2}{9} = \\dfrac{1}{15}$', 'Exactly one fused: $\\dfrac{3}{10} \\times \\dfrac{7}{9} + \\dfrac{7}{10} \\times \\dfrac{3}{9} = \\dfrac{42}{90} = \\dfrac{7}{15}$'], v: bulbTree, n: 'A tree diagram keeps the stages in order. The first bulb is fused with probability three tenths. If it was fused, nine bulbs remain with two fused, so the next branch is two ninths. Multiply along the path for both fused: one fifteenth. For exactly one fused, there are two paths, fused then good and good then fused. Add them to get seven fifteenths.' }),
    sl('example', 'Worked example 4: three events in a row', { b: 'A bag has $4$ red, $3$ green and $2$ yellow balls. Three are drawn one by one without replacement. Find the probability of red, then green, then yellow.', m: ['\\dfrac{4}{9} \\times \\dfrac{3}{8} \\times \\dfrac{2}{7} = \\dfrac{24}{504} = \\dfrac{1}{21}'], v: bagTree3, n: 'With three draws, apply the rule three times. Red first has probability four ninths. Given that, eight balls remain with three green, so three eighths. Given both, seven balls remain with two yellow, so two sevenths. Multiply the three factors to get one twenty first. Notice each factor depends on what happened before.' }),
    sl('check', 'Quick check: is the order irrelevant?', { b: 'True or false: $P(A \\mid B) = P(B \\mid A)$ for all events.', chk: 'tf1', n: 'Think back to the cricket and football survey. Did the two conditional probabilities come out equal? Decide, and try to give a reason.' }),
    sl('concept', 'Independent events', { b: '$E$ and $F$ are **independent** if knowing one does not change the probability of the other: $P(E \\mid F) = P(E)$. Equivalently,', m: ['P(E \\cap F) = P(E)\\,P(F)'], v: kingHeart, n: 'Sometimes information changes nothing. Draw one card. Knowing it is a heart does not change the chance that it is a king, still one in thirteen. Such events are independent. The test is simple: the probability of both equals the product of the separate probabilities. For the king of hearts, one over fifty two equals one thirteenth times one quarter.' }),
    sl('diagram', 'Independent is not mutually exclusive', { b: 'With non-zero probabilities, mutually exclusive events are **never** independent.', v: exclVsIndep, n: 'Students often confuse these two words. Mutually exclusive means the events cannot happen together, so the probability of both is zero. Independent means one event gives no information about the other. If two events with non-zero probabilities are mutually exclusive, then knowing one happened tells you the other did not, which is a lot of information. So they cannot be independent.' }),
    sl('example', 'Worked example 5: at least one', { b: 'A Pune startup runs three servers that fail on a given day independently with probabilities $0.1$, $0.05$ and $0.02$. Find the probability that at least one fails.', ul: ['All work: $0.9 \\times 0.95 \\times 0.98 = 0.8379$', 'At least one fails: $1 - 0.8379 = 0.1621$'], v: serverFlow, n: 'At least one failure can happen in many ways, so use the complement. For independent events the complements are also independent, so the chance that all three servers work is the product of point nine, point nine five and point nine eight. That is about point eight four. Subtract from one to get the chance that at least one fails.' }),
    sl('check', 'Quick check: two throws of a die', { b: 'A die is thrown twice. Find the probability of a six first and an odd number second.', chk: 'm12', n: 'The two throws do not influence each other. Find each probability separately and decide whether to add or multiply.' }),
    sl('summary', 'Summary of Part 1', { ul: ['$P(E \\mid F) = \\dfrac{P(E \\cap F)}{P(F)}$; count inside $F$ for equally likely outcomes', 'Conditional probability obeys the usual rules, including the complement rule', 'Multiplication rule for events in sequence; tree diagrams', 'Independent: $P(E \\cap F) = P(E)P(F)$; not the same as mutually exclusive'], v: summary1, n: 'Let us sum up. Conditional probability divides the overlap by the given event. It behaves like ordinary probability on the reduced sample space. The multiplication rule handles events in sequence, and tree diagrams organise the stages. Independent events satisfy the product rule, and they must never be confused with mutually exclusive events.' }),
    sl('exam-tips', 'Exam tips for Part 1', { ul: ['Write the given event first and name it ($F$); everything is divided by $P(F)$', 'In two-way tables, divide by the **row or column total** of the given event', 'For "without replacement", the second factor is conditional: totals drop by one', 'Independence must be **shown** with numbers: compare $P(E \\cap F)$ with $P(E)P(F)$', 'Use the complement for "at least one"'], n: 'Some exam tips. Always name the given event first and divide by its probability. In tables, use the row or column total of the given group, not the grand total. Without replacement, the second draw has one fewer item. When asked about independence, show the comparison with numbers; a word answer alone does not earn the mark. And for at least one, use the complement.' }),
  ],
});

// ---------------------------------------------------------------- deck 2
const d2 = deck({
  part: 2,
  title: "Probability — Part 2: Total probability and Bayes' theorem",
  goals: ['Recognise a partition of the sample space', 'Find the probability of an event through several causes (total probability)', "Reverse a conditional probability with Bayes' theorem", 'Interpret posterior probabilities in real situations'],
  slides: [
    sl('title', "Probability, Part 2: Total probability and Bayes' theorem", { b: 'From causes to effects, and back again.', v: bagTree, n: 'Welcome to part two. Many situations have several possible causes for the same outcome: a ball may come from either of two bags, a late parcel from either of two vans. In this part you will learn to find the chance of the outcome by adding over the causes, and then to run the argument backwards: having seen the outcome, how likely is each cause?' }),
    sl('concept', 'What you will be able to do', { ul: ['Recognise a **partition** of the sample space', 'Use the **theorem of total probability**', "Apply **Bayes' theorem** to find the probability of a cause", 'Read answers from **trees** and **tables**'], n: 'Here are the goals for part two. A partition splits the sample space into non-overlapping pieces. The theorem of total probability adds up the contributions of the pieces. Bayes theorem then reverses the direction of the conditional probability. Trees and tables will make every calculation visible and easy to check.' }),
    sl('diagram', 'Partition of the sample space', { b: 'Events $E_1, E_2, \\ldots, E_n$ form a **partition** of $S$ if they are pairwise disjoint, their union is $S$ and each $P(E_i) > 0$.', v: part3, n: 'A partition cuts the sample space into pieces that do not overlap and together cover everything, like strips of a rectangle. Every outcome lies in exactly one piece. Typical partitions are the bags a ball can come from, the machines that make a part, or the routes a parcel can take. The event A in the picture is cut into three parts by the strips.' }),
    sl('concept', 'Theorem of total probability', { b: 'If $E_1, \\ldots, E_n$ partition $S$, then for any event $A$:', m: ['P(A) = P(E_1)P(A \\mid E_1) + P(E_2)P(A \\mid E_2) + \\cdots + P(E_n)P(A \\mid E_n)'], ul: ['Each term is $P(A \\cap E_i)$ by the multiplication rule', 'The pieces $A \\cap E_i$ do not overlap, so their probabilities add'], v: part3, n: 'Since the strips do not overlap, the event A splits into pieces, one in each strip. By the multiplication rule each piece has probability equal to the probability of the strip times the probability of A given that strip. Add them up and you get the probability of A. In a tree, this means: multiply along each path that ends in A, then add the paths.' }),
    sl('example', 'Worked example 1: two bags', { b: 'Bag I has $5$ white and $3$ black balls; bag II has $2$ white and $6$ black. A coin is tossed to choose a bag and one ball is drawn. Find $P(\\text{white})$.', ul: ['**Partition:** bag I, bag II, each with probability $\\dfrac{1}{2}$', '**Likelihoods:** $P(W \\mid \\text{I}) = \\dfrac{5}{8}$, $P(W \\mid \\text{II}) = \\dfrac{2}{8}$', '**Total:** $\\dfrac{1}{2} \\times \\dfrac{5}{8} + \\dfrac{1}{2} \\times \\dfrac{2}{8} = \\dfrac{7}{16}$'], v: bagTree, n: 'The two bags form the partition, each chosen with probability one half. From bag one, white has probability five eighths; from bag two, two eighths. Multiply along each white path and add: five sixteenths plus two sixteenths gives seven sixteenths. Notice that the answer lies between the two bag rates, closer to whichever bag is more likely.' }),
    sl('example', 'Worked example 2: three routes', { b: 'A Chennai courier sends parcels by three routes with probabilities $\\dfrac{1}{2}$, $\\dfrac{1}{3}$, $\\dfrac{1}{6}$. A parcel is delayed with probability $\\dfrac{1}{10}$, $\\dfrac{1}{5}$, $\\dfrac{1}{4}$ on these routes. Find $P(\\text{delay})$.', m: ['P(D) = \\dfrac{1}{20} + \\dfrac{1}{15} + \\dfrac{1}{24} = \\dfrac{6 + 8 + 5}{120} = \\dfrac{19}{120}'], v: routeTable, n: 'A table works as well as a tree. List each route with its probability and its delay rate, multiply across each row, and add the last column. The products are one twentieth, one fifteenth and one twenty fourth. With a common denominator of one hundred and twenty they add to nineteen over one hundred and twenty.' }),
    sl('check', 'Quick check: the missing piece', { b: 'Three events form a partition. Two of them have probabilities $\\dfrac{1}{2}$ and $\\dfrac{1}{3}$. Find the third.', chk: 'm18', n: 'Remember the two key facts about a partition: the pieces do not overlap, and together they make up the whole sample space. What must their probabilities add up to?' }),
    sl('concept', "Bayes' theorem", { b: 'After observing $A$, the probability of the cause $E_i$ is', m: ['P(E_i \\mid A) = \\dfrac{P(E_i)\\,P(A \\mid E_i)}{\\sum_{j} P(E_j)\\,P(A \\mid E_j)}'], ul: ['$P(E_i)$: **prior** (before seeing $A$)', '$P(A \\mid E_i)$: **likelihood**', '$P(E_i \\mid A)$: **posterior** (after seeing $A$)'], v: bayesFlow, n: 'Bayes theorem answers the reverse question. We know how likely the outcome is under each cause. Having seen the outcome, how likely is each cause? The answer is one path product divided by the sum of all the path products, which is just the total probability. The probability before the evidence is called the prior, and the one after is called the posterior.' }),
    sl('diagram', 'Reading Bayes from a tree', { b: 'Keep only the paths that end in the observed outcome; the posterior is one path over the sum of these paths.', v: bayesTreeAns, n: 'Here is the bag tree again, but with only the white paths kept, because we know the ball was white. The path through bag one has probability five sixteenths and the path through bag two has two sixteenths. The chance that the ball came from bag one is its path divided by the total of the kept paths.' }),
    sl('example', 'Worked example 3: which bag?', { b: 'In worked example 1 the ball drawn is white. Find the probability that it came from bag I.', m: ['P(\\text{I} \\mid W) = \\dfrac{\\frac{1}{2} \\times \\frac{5}{8}}{\\frac{7}{16}} = \\dfrac{5/16}{7/16} = \\dfrac{5}{7}'], ul: ['Prior $\\dfrac{1}{2}$ rises to posterior $\\dfrac{5}{7}$: bag I has more white balls', 'Then $P(\\text{II} \\mid W) = \\dfrac{2}{7}$; the two add to $1$ ✓'], v: bagTree, n: 'Use the formula with the total we found earlier. The numerator is the bag one path, five sixteenths. The denominator is the total chance of white, seven sixteenths. So the posterior is five sevenths. Before the draw, each bag had probability one half. Seeing white makes bag one more likely, because it has more white balls. The other posterior is two sevenths.' }),
    sl('example', 'Worked example 4: a screening test', { b: 'At a Pune health camp $5\\%$ of people have a vitamin deficiency. A quick test is positive for $90\\%$ of deficient people and for $10\\%$ of the others. A person tests positive. How likely is the deficiency?', ul: ['Think of $1000$ people: $50$ deficient, $45$ of them positive', '$950$ not deficient, $95$ of them positive', '$P(\\text{deficient} \\mid +) = \\dfrac{45}{140} = \\dfrac{9}{28} \\approx 0.32$'], v: screenTable, n: 'Imagine one thousand people. Fifty are deficient, and forty five of them test positive. Nine hundred and fifty are not, yet ten percent of them, ninety five people, also test positive. So out of one hundred and forty positives, only forty five are truly deficient: about one in three. The false alarms from the large healthy group swamp the true positives.' }),
    sl('check', 'Quick check: posteriors together', { b: 'What do the posterior probabilities over a whole partition add up to?', chk: 'm16', n: 'After seeing the evidence, exactly one of the causes must still be the true one. Use that to decide.' }),
    sl('diagram', 'Why the prior matters', { b: 'For the screening test above, the posterior after a positive result depends strongly on the prior.', v: priorPlot, n: 'This graph shows the posterior after a positive test for different priors. If the condition affects one person in ten, a positive result raises the chance to one half. If it affects half the people, a positive result raises it to nine tenths. The curve is always above the diagonal, so a positive test always raises the probability, but a rare condition still leaves real doubt.' }),
    sl('example', 'Worked example 5: three shifts', { b: 'A Hyderabad call centre handles $40\\%$, $35\\%$ and $25\\%$ of its calls in the morning, evening and night shifts. The complaint rates are $2\\%$, $3\\%$ and $4\\%$. A complaint arrives. Which shift most likely handled the call?', ul: ['$P(C) = 0.008 + 0.0105 + 0.01 = 0.0285$', 'Posteriors: $\\dfrac{0.008}{0.0285} = \\dfrac{16}{57}$, $\\dfrac{0.0105}{0.0285} = \\dfrac{7}{19}$, $\\dfrac{0.01}{0.0285} = \\dfrac{20}{57}$', 'Evening is most likely; check $\\dfrac{16 + 21 + 20}{57} = 1$ ✓'], v: shiftTable, n: 'Fill a table with each shift, its share of calls, its complaint rate and the product. The products add to zero point zero two eight five, the total chance of a complaint. Divide each product by this total. The evening shift wins with seven nineteenths, even though the night shift has the highest complaint rate, because the evening shift handles more calls.' }),
    sl('concept', 'Common traps', { b: 'Decide the **direction** of the question before you calculate.', v: trapTable, n: 'Before calculating, ask which way the question runs. If it asks for the chance of an outcome that can arise from several causes, use total probability. If it asks for the chance of a cause after the outcome is seen, use Bayes. The chance of the outcome given a cause is usually stated in the question. And always check that your posteriors add to one.' }),
    sl('check', 'Quick check: what makes a partition?', { b: 'True or false: the events in the theorem of total probability must be disjoint, have non-zero probabilities and cover the whole sample space.', chk: 'tf5', n: 'Recall the definition of a partition from the start of this part. Do all three conditions belong to it?' }),
    sl('diagram', 'Choosing the right tool', { b: 'One chapter, five tools: match the question to the tool.', v: toolFlow, n: 'Here is the whole chapter in one chart. A given that phrase calls for conditional probability. Events in a sequence call for the multiplication rule. Unrelated trials call for independence. An outcome reached through several causes calls for total probability. And a question about the cause after the outcome is Bayes theorem.' }),
    sl('summary', 'Summary of Part 2', { ul: ['A partition: disjoint, covers $S$, each piece has non-zero probability', 'Total probability: add $P(E_i)P(A \\mid E_i)$ over the partition', "Bayes' theorem: posterior = one product ÷ the total", 'Posteriors add to $1$; priors and likelihoods both matter'], v: summary2, n: 'To sum up part two. A partition splits the sample space into disjoint pieces. The theorem of total probability adds the products of prior and likelihood over the pieces. Bayes theorem divides one of those products by the total to get a posterior. Posteriors always add to one, and both the prior and the likelihood shape the answer.' }),
    sl('exam-tips', 'Exam tips for Part 2', { ul: ['Define the events in words first: $E_1$, $E_2$, … and $A$', 'Write priors and likelihoods as a list or tree before any formula (1 mark)', 'Show $P(A)$ by total probability (1 mark), then the Bayes ratio (1–2 marks)', 'Convert percentages to decimals or fractions consistently', 'Check that posteriors add to $1$; state the conclusion in words'], n: 'For long answers on Bayes theorem, define every event in words. Then list the priors and the likelihoods; this usually earns a mark by itself. Show the total probability step clearly before the final ratio. Be consistent with percentages, decimals and fractions. Finally, check that the posteriors add to one, and finish with a sentence that answers the question.' }),
  ],
});

// ---------------------------------------------------------------- notes
const notes = {
  unit: 'cbse-12-mathematics-ch13', version: 1, title: 'Probability — chapter notes', language: 'en',
  sections: [
    { heading: '1. Conditional probability', body_md: 'If $E$ and $F$ are events of a sample space $S$ with $P(F) \\ne 0$, the **conditional probability of $E$ given $F$** is\n\n$$P(E \\mid F) = \\dfrac{P(E \\cap F)}{P(F)}.$$\n\nKnowing that $F$ has happened rules out every outcome outside $F$; the outcomes inside $F$ stay equally likely. For equally likely outcomes, $P(E \\mid F) = \\dfrac{n(E \\cap F)}{n(F)}$.\n\nExample: two dice, given at least one six ($11$ outcomes), the probability that the sum is at least $10$ is $\\dfrac{5}{11}$.', key_terms: [{ term: 'Conditional probability', definition_md: 'The probability of $E$ when $F$ is known to have happened: $P(E \\mid F)$.' }, { term: 'Reduced sample space', definition_md: 'The given event $F$, used as the new sample space.' }], formulas: [{ latex: 'P(E \\mid F) = \\dfrac{P(E \\cap F)}{P(F)}, \\quad P(F) \\ne 0', label: 'Definition' }], visual: shrink, topic_ids: [topic(1)] },
    { heading: '2. Properties of conditional probability', body_md: 'For a fixed event $F$ with $P(F) > 0$:\n\n- $P(S \\mid F) = P(F \\mid F) = 1$\n- $0 \\le P(E \\mid F) \\le 1$\n- $P(A \\cup B \\mid F) = P(A \\mid F) + P(B \\mid F) - P(A \\cap B \\mid F)$\n- $P(E\' \\mid F) = 1 - P(E \\mid F)$\n\nIn general $P(E \\mid F) \\ne P(F \\mid E)$: the numerators are the same, the denominators are not. In a two-way table, divide by the **row or column total of the given group**.', key_terms: [{ term: 'Complement rule (conditional)', definition_md: '$P(E\' \\mid F) = 1 - P(E \\mid F)$.' }], formulas: [{ latex: "P(E' \\mid F) = 1 - P(E \\mid F)", label: 'Complement' }], visual: propTable, topic_ids: [topic(1)] },
    { heading: '3. Multiplication theorem', body_md: 'From the definition,\n\n$$P(E \\cap F) = P(E)\\,P(F \\mid E) = P(F)\\,P(E \\mid F).$$\n\nFor three events, $P(E \\cap F \\cap G) = P(E)\\,P(F \\mid E)\\,P(G \\mid E \\cap F)$.\n\nUse it for events in **sequence**, especially draws **without replacement**, where each later factor is conditional on the earlier draws. A **tree diagram** shows the stages: multiply along a path, add different paths.\n\nExample: $10$ bulbs with $3$ fused, two drawn without replacement: $P(\\text{both fused}) = \\dfrac{3}{10} \\times \\dfrac{2}{9} = \\dfrac{1}{15}$.', key_terms: [{ term: 'Tree diagram', definition_md: 'Branches for each stage, labelled with (conditional) probabilities; path probability = product along the path.' }], formulas: [{ latex: 'P(E \\cap F \\cap G) = P(E)\\,P(F \\mid E)\\,P(G \\mid E \\cap F)', label: 'Three events' }], visual: bulbTree, topic_ids: [topic(2)] },
    { heading: '4. Independent events', body_md: 'Events $E$ and $F$ are **independent** if $P(E \\cap F) = P(E)\\,P(F)$; equivalently (when the probabilities are non-zero) $P(E \\mid F) = P(E)$ and $P(F \\mid E) = P(F)$.\n\n- If $E$, $F$ are independent, so are $E$ and $F\'$, $E\'$ and $F$, and $E\'$ and $F\'$.\n- Three events are **mutually independent** if every pair satisfies the product rule **and** $P(E \\cap F \\cap G) = P(E)P(F)P(G)$.\n- For independent events, $P(\\text{at least one}) = 1 - P(E\')P(F\')\\cdots$.\n- **Mutually exclusive** ($P(E \\cap F) = 0$) is a different idea: with non-zero probabilities, mutually exclusive events are never independent.\n\nExample: one card from a pack; "king" and "heart" are independent since $\\dfrac{1}{52} = \\dfrac{1}{13} \\times \\dfrac{1}{4}$.', key_terms: [{ term: 'Independent events', definition_md: 'Events with $P(E \\cap F) = P(E)P(F)$: knowing one does not change the chance of the other.' }, { term: 'Mutually exclusive events', definition_md: 'Events that cannot happen together: $P(E \\cap F) = 0$.' }], formulas: [{ latex: 'P(E \\cap F) = P(E)\\,P(F)', label: 'Independence test' }, { latex: "P(E \\cup F) = 1 - P(E')\\,P(F')", label: 'At least one (independent)' }], visual: exclVsIndep, topic_ids: [topic(2)] },
    { heading: '5. Partition and the theorem of total probability', body_md: 'Events $E_1, \\ldots, E_n$ form a **partition** of $S$ if $E_i \\cap E_j = \\varnothing$ for $i \\ne j$, $E_1 \\cup \\cdots \\cup E_n = S$ and $P(E_i) > 0$ for every $i$.\n\n**Theorem of total probability:** for any event $A$,\n\n$$P(A) = \\sum_{i=1}^{n} P(E_i)\\,P(A \\mid E_i).$$\n\nIn a tree: multiply along every path ending in $A$ and add. Example: bag I ($5$ white, $3$ black) and bag II ($2$ white, $6$ black) chosen by a coin: $P(W) = \\dfrac{7}{16}$.', key_terms: [{ term: 'Partition', definition_md: 'Disjoint events with non-zero probabilities whose union is the sample space.' }, { term: 'Total probability', definition_md: 'The probability of $A$ as a sum over the pieces of a partition.' }], formulas: [{ latex: 'P(A) = \\sum_{i=1}^{n} P(E_i)\\,P(A \\mid E_i)', label: 'Total probability' }], visual: part3, topic_ids: [topic(3)] },
    { heading: "6. Bayes' theorem", body_md: 'If $E_1, \\ldots, E_n$ partition $S$ and $P(A) > 0$,\n\n$$P(E_i \\mid A) = \\dfrac{P(E_i)\\,P(A \\mid E_i)}{\\sum_{j=1}^{n} P(E_j)\\,P(A \\mid E_j)}.$$\n\n- $P(E_i)$: **prior**; $P(A \\mid E_i)$: **likelihood**; $P(E_i \\mid A)$: **posterior**.\n- The posteriors add to $1$.\n- A rare cause can stay unlikely even after strong evidence: in a screening test with prior $5\\%$, a positive result gives only $\\dfrac{9}{28} \\approx 0.32$.\n\nExample: a complaint at a call centre with shifts $40\\%$, $35\\%$, $25\\%$ and complaint rates $2\\%$, $3\\%$, $4\\%$: $P(C) = 0.0285$; posteriors $\\dfrac{16}{57}$, $\\dfrac{7}{19}$, $\\dfrac{20}{57}$.', key_terms: [{ term: 'Prior probability', definition_md: 'The probability of a cause before the evidence.' }, { term: 'Posterior probability', definition_md: 'The probability of a cause after the evidence, from Bayes\' theorem.' }, { term: 'Likelihood', definition_md: 'The probability of the evidence under a given cause, $P(A \\mid E_i)$.' }], formulas: [{ latex: 'P(E_i \\mid A) = \\dfrac{P(E_i)\\,P(A \\mid E_i)}{\\sum_{j} P(E_j)\\,P(A \\mid E_j)}', label: "Bayes' theorem" }], visual: screenTable, visuals: [priorPlot], topic_ids: [topic(3)] },
    { heading: '7. Strategy: choosing the tool', body_md: '1. Define every event in words.\n2. Read the question: does it say **given**? Which event is known?\n3. Events in order → multiplication rule (tree). Unrelated trials → independence.\n4. Outcome through several causes → total probability. Cause after the outcome → Bayes.\n5. Check: probabilities between $0$ and $1$; posteriors add to $1$; the answer makes sense in context.\n\n*Not in the 2026–27 syllabus:* random variables and their probability distributions, mean and variance of a random variable, Bernoulli trials and the binomial distribution.', key_terms: [{ term: 'Direction of a conditional', definition_md: 'Which event is given: $P(A \\mid E)$ is a likelihood, $P(E \\mid A)$ a posterior.' }], formulas: [], visual: toolFlow, topic_ids: [topic(1), topic(2), topic(3)] },
  ],
  exam_tips_md: '**How marks are awarded**\n- *Conditional probability (1–3 marks):* given event identified, the reduced sample space or the formula, answer simplified.\n- *Independence (2–3 marks):* $P(E)$, $P(F)$ and $P(E \\cap F)$ found, comparison written out, conclusion in words.\n- *Multiplication rule (2–3 marks):* each factor with the correct (conditional) denominator, product, all orders counted when the order is not fixed.\n- *Bayes (4–5 marks):* events defined (1), priors and likelihoods (1), total probability (1), ratio (1), answer with conclusion (1).\n\n**Common mistakes**\n1. Dividing by the wrong event: $P(A \\mid B)$ uses $P(B)$, not $P(A)$.\n2. Using the grand total instead of the row or column total in a two-way table.\n3. Treating draws without replacement as independent.\n4. Calling mutually exclusive events independent.\n5. Adding probabilities of independent events to get "both".\n6. Forgetting one of the orders (white-black and black-white).\n7. In Bayes, using the prior as the answer or forgetting to divide by the total.\n8. Mixing percentages and decimals in one line.',
  status: 'draft', provenance: d1.provenance,
};

